REV={}
def R(n,key,explanation,ids,status='agrees',refs=''):
 REV[n]=dict(reviewedAnswer=key,explanation=explanation,cardRefs=ids.split(),reviewStatus=status,refs=refs.split())
R(1,'C','Ngừng hẳn, không phục hồi các quá trình duy trì vật chất và năng lượng làm cơ thể không thể tiếp tục sống. Không nhầm với ngủ hay giảm chuyển hóa.','@1','clarified')
R(2,'A','Sinh vật tự dưỡng gồm quang tự dưỡng và hóa tự dưỡng; hai nhóm khác nhau về nguồn năng lượng dùng để tổng hợp chất hữu cơ từ carbon vô cơ.','qa21-g11-l1-s5-32eda280f3')
R(3,'B','Trao đổi chất và chuyển hóa năng lượng cung cấp nguyên liệu và năng lượng để cơ thể tồn tại, sinh trưởng và phát triển.','qa21-g11-l1-s1-e3257161b7')
R(4,'A','Hai quá trình gắn bó: các phản ứng biến đổi chất có trao đổi năng lượng; nhiều hoạt động vận chuyển chất cũng cần năng lượng.','@4')
R(5,'B','Đề đang nói các chất dư thừa/không được sử dụng cần đào thải. Không phải mọi chất chưa dùng ngay đều là chất thải, vì cơ thể còn có chất dự trữ.','qa21-g11-l1-s1-cd75b9ca73','clarified')
R(6,'D','Quang năng là nguồn đầu vào chủ yếu của phần lớn hệ sinh thái. ATP là dạng trung gian trao đổi năng lượng trong tế bào.','@6')
R(7,'C','Sự sống dựa trên cả trao đổi chất và chuyển hóa năng lượng. Hai ý này không phải hai cách sống tách biệt.','qa21-g11-l1-s1-e3257161b7 @4')
R(8,'A','Năng lượng có thể được giữ trong chất hữu cơ, dùng cho hoạt động sống và tỏa ra môi trường dưới dạng nhiệt. Các tỷ lệ không cố định như cách nói “hai phần” ở một số đáp án.','qa21-g11-l1-s3-d133472ddd')
R(9,'Không có đáp án chuẩn diễn đạt rõ trong các lựa chọn gốc','Khóa A của tài liệu nhầm ánh sáng (năng lượng) với chất. Ví dụ thu nhận chất rõ ràng là rễ hấp thụ nước hoặc lá nhận CO₂. Không giữ câu gốc làm trắc nghiệm chấm tự động.','qa21-g11-l4-s1-4a04da1623 qa21-g11-l1-s3-5e37e1bade','ambiguous','metabolism photosynthesis')
R(10,'A','Cả thực vật và động vật đều hô hấp tế bào, chuyển năng lượng của chất hữu cơ sang dạng có thể sử dụng như ATP; không tạo năng lượng từ hư vô.','qa21-g11-l6-s1-5b56ac186d','clarified')
R(11,'A','Theo vai trò sinh thái, nhóm dị dưỡng thường gồm sinh vật tiêu thụ và sinh vật phân giải.','@11')
R(12,'C','Cơ thể sống là hệ mở, đồng thời trao đổi vật chất và năng lượng với môi trường.','@12')
R(13,'B','Sinh vật tự dưỡng là sinh vật sản xuất: tạo chất hữu cơ từ nguồn carbon vô cơ, cung cấp vật chất và năng lượng cho các bậc dinh dưỡng khác.','qa21-g11-l1-s5-46fe9b53f1 qa21-g11-l4-s2-dafd8652a0')
R(14,'A','Năng lượng giải phóng khi phân giải chất hữu cơ có thể được tích lũy trong ATP. Nước và oxygen không phải nguồn năng lượng hữu cơ được “biến thành năng lượng”.','qa21-g11-l1-s3-3300fe4134','clarified')
R(15,'D','Các chất tới tế bào thông qua hệ mạch ở thực vật có mạch và hệ tuần hoàn ở những động vật có hệ này. Cần giới hạn phạm vi, vì không phải mọi động vật đều có hệ tuần hoàn.','@15','clarified')
R(16,'D là phương án dự kiến; lí do cần bổ sung','Lá không ăn thịt nhưng vẫn trao đổi khí, nhận nước/khoáng và thực hiện quang hợp, hô hấp. “Không ăn thịt” không có nghĩa là “không trao đổi chất”; câu D gốc giải thích chưa đủ.','qa21-g11-l1-s5-46fe9b53f1 qa21-g11-l4-s1-4a04da1623','clarified')
R(17,'C theo chuỗi chuyển hóa được hỏi','Nitrogen hữu cơ được ammonium hóa thành NH₄⁺, rồi có thể nitrate hóa thành NO₃⁻. Cây có thể hấp thụ NH₄⁺ trực tiếp: không bắt buộc mọi nguồn N đều phải qua cả hai bước.','qa21-g11-l2-s7-8e5af7b931 qa21-g11-l2-s7-f39e3e77f5','clarified')
R(18,'D','Dịch mạch gỗ chủ yếu gồm nước và ion khoáng; “chủ yếu” không loại trừ các chất hòa tan khác.','qa21-g11-l2-s3-4775b92ecb')
R(19,'C','Lá là cơ quan thoát hơi nước chủ yếu ở đa số cây được học, phần lớn qua khí khổng.','qa21-g11-l2-s4-7dbce942fe')
R(20,'A','Ca là nguyên tố đa lượng; Cl, Fe và Mo là các nguyên tố vi lượng của thực vật.','@20')
R(21,'C (70% làm tròn)','Số thường dùng là khoảng 71% diện tích bề mặt Trái Đất được nước bao phủ; đáp án 70% gần đúng nhất trong đề.','@21','clarified','earth')
R(22,'C','Quản bào và phần tử mạch ống là các tế bào dẫn của mạch gỗ; tế bào nội bì/lông hút/biểu bì không phải các phần tử dẫn này.','@22')
R(23,'A trong phạm vi nitrogen khoáng','Hai dạng vô cơ chủ yếu được rễ hấp thụ là NO₃⁻ và NH₄⁺. Không suy rộng từ “chủ yếu” thành mọi loài cây chỉ có thể lấy N ở đúng hai dạng trong mọi điều kiện.','qa21-g11-l2-s6-f216acc436','clarified')
R(24,'A nếu nói về các phần tử dẫn trưởng thành','Quản bào và phần tử mạch ống đã chết khi dẫn nước. Toàn bộ mô mạch gỗ vẫn có nhu mô sống, nên câu gốc dùng “mạch gỗ” quá rộng.','@24','clarified')
R(25,'D','Đó là tiêu chí của nguyên tố thiết yếu; thiết yếu không đồng nghĩa với đa lượng.','@25')
R(26,'D','Nước có thể ở thể rắn, lỏng hoặc khí tùy điều kiện nhiệt độ và áp suất.','@26')
R(27,'B','Phản nitrate hóa chuyển nitrogen ở nitrate về các dạng khí, trong đó có N₂.','qa21-g11-l2-s7-be54098c79')
R(28,'C là ý định của đề; C/D chồng lấn','Lông hút là phần kéo dài của tế bào biểu bì rễ. Vì vậy chọn “lông hút” và loại hoàn toàn “biểu bì” mà không nói rõ dạng chuyên hóa sẽ gây mơ hồ.','qa21-g11-l2-s2-980c010916','ambiguous')
R(29,'A','Nitrogenase nhạy với oxygen. Cố định N₂ cần năng lượng và lực khử; vi sinh vật sống nơi có oxygen phải có cơ chế bảo vệ enzyme.','@29','clarified')
R(30,'Không có lựa chọn hoàn toàn đúng khi hiểu như quy luật chung','Khóa D chỉ mô tả một hướng thường gặp. Mạch rây đi từ cơ quan nguồn đến nơi nhận, có thể lên hoặc xuống. A sai cơ chế; B dùng “luôn” quá tuyệt đối; C sai thành phần chủ yếu.','qa21-g11-l2-s3-8a9646c4b5','ambiguous','transport')
R(31,'Cần sửa câu hỏi; không thể giữ khóa B như một kết luận chắc chắn','Nước tự do có thể làm giảm độ nhớt của chất nguyên sinh, nên B không phải một vai trò sai nói chung. D lại trộn tính dung môi với làm mát do bay hơi. Câu thay thế kiểm tra riêng cơ chế làm mát.','@31','ambiguous','water')
R(32,'B theo phạm vi thoát nước qua cuticle','Với các điều kiện khác tương đương, mất nước qua bề mặt cuticle phụ thuộc tính thấm/độ dày lớp cuticle và diện tích. Nếu hỏi toàn bộ thoát hơi qua lá thì còn phải xét khí khổng, độ ẩm, nhiệt độ...','qa21-g11-l2-s4-88565097dc','clarified')
R(33,'B là cách nói giản lược','Chênh lệch nồng độ là một phần nguyên nhân. Đối với ion qua màng, hướng thụ động chính xác hơn là xuôi gradient điện hóa, gồm cả điện thế màng.','@33','clarified')
R(34,'A','Nhiều nguyên tố vi lượng là thành phần hay yếu tố hỗ trợ hoạt động enzyme. “Lượng nhỏ” không có nghĩa không thiết yếu.','@34')
R(35,'A','Câu mô tả hấp thụ ngược gradient cần năng lượng. Trong sinh lí màng, gradient điện hóa là khái niệm đầy đủ hơn chỉ chênh lệch nồng độ.','qa21-g11-l2-s2-5029e34076','clarified')
R(36,'D nếu giữ các điều kiện khác tương đương','Không khí khô làm tăng chênh lệch hơi nước giữa lá và không khí. Thực tế cây có thể đóng khí khổng khi thiếu nước, nên không suy tỷ lệ cố định.','qa21-g11-l2-s11-46af61d3c4','clarified')
R(37,'D trong cách so sánh thông thường của đề','Tăng số khí khổng mở không phải cơ chế đơn giản giúp giảm mất nước; gai, lông và khí khổng chìm có thể hạn chế mất nước. Mật độ khí khổng riêng lẻ không quyết định toàn bộ chịu hạn.','@37 qa21-g11-l2-s4-88565097dc','clarified')
R(38,'B khi mục đích là ủ ấm trong rét','Phủ rơm cách nhiệt, giúp hạn chế tác hại của lạnh lên vùng rễ. Ở bối cảnh khác, lớp phủ còn có thể giảm nóng và giữ ẩm.','@38','clarified','mulch')
R(39,'C là đáp án dự kiến; không phải quy luật cấy luôn nhanh hơn gieo thẳng','Đề muốn nhắc sự tái sinh/phát triển rễ sau cấy. Thực tế nhổ cấy còn có thể gây sốc và tổn thương rễ; kết quả phụ thuộc giống, tuổi mạ và kĩ thuật. Không đưa mệnh đề so sánh tuyệt đối này vào câu chấm tự động.','qa21-g11-l2-s2-980c010916','needs-context','roots rice')
R(40,'C','15 phút = 0,25 giờ. Cường độ = lượng nước mất/(diện tích × thời gian) = 0,08/(0,5 × 0,25) = 0,64 g/(dm²·giờ). Bỏ qua các nguyên nhân biến đổi khối lượng khác theo mô hình thí nghiệm.','qb22-qb11-mcTDNVK-level3-9')
R(41,'C theo giả thiết vận chuyển trong đề','Ngọn nhận đỏ và vàng; rễ nhận đỏ. Cần giả thiết ngọn/rễ đều là nơi nhận chất hữu cơ và chất chỉ thị thực sự theo từng dòng dẫn. Không suy hướng dòng từ màu thuốc nhuộm một cách độc lập.','@41 qa21-g11-l2-s3-4775b92ecb','clarified')
R(42,'A là phương án phù hợp','Ca tham gia thành tế bào, ổn định màng và điều hòa tín hiệu/enzyme. B mô tả Mg, C mô tả P, D gần vai trò Fe. Không coi Ca là nguyên tử trung tâm diệp lục.','@42','clarified')
R(43,'C — sửa khóa A của tài liệu','Xới đất làm đất thoáng, tăng khả năng cung cấp oxygen cho rễ hô hấp. A có thể là lợi ích phụ, nhưng C trả lời trực tiếp nhất tác dụng với cây trong câu hỏi.','qa21-g11-l6-s6-7ab1e7589b','corrected','transport')
R(44,'C','Nhiều ion khoáng hòa tan trong nước và được hấp thụ, vận chuyển cùng pha nước; không có nghĩa mọi chất khoáng đều tan tốt như nhau.','qa21-g11-l2-s1-eada8daa0a')
R(45,'A/C chồng lấn; cần sửa để chỉ có một đáp án','C nêu trực tiếp điều kiện nồng độ chất tan; A thêm thoát hơi nước nhưng không loại trừ C. Lực căng do thoát hơi nước là thành phần áp suất, không đồng nghĩa với nồng độ chất tan.','@45','ambiguous','transport')
R(46,'C; trùng mục tiêu và thí nghiệm với câu 41','Hai câu cùng mô tả đỏ trong mạch rây và vàng trong mạch gỗ. Dùng chung các câu luyện, không nhân đôi bản ghi chỉ vì khác mã.','@41 qa21-g11-l2-s3-4775b92ecb','clarified')
R(47,'D là nhóm ví dụ phù hợp, nhưng mô tả sa mạc quá hẹp','CAM thường giúp tiết kiệm nước ở nhiều cây mọng nước. Dứa và mọi cây CAM không nhất thiết sống ở sa mạc.','@53 qa21-g11-l4-s9-7389240e01','clarified')
R(48,'B','Mô giậu ở lá hai mặt điển hình có tế bào xếp khá sát, chứa nhiều lục lạp.','@48')
R(49,'B','Rong được chiếu sáng quang hợp giải phóng O₂. Hình của câu này khác câu 59 dù cùng mã in MB-QHOTV-L2-001.','qa21-g11-l4-s2-c0aa8a7c14','clarified')
R(50,'A trong mô hình lá hai mặt','Mô giậu thường nằm ngay dưới biểu bì trên. Không phải mọi lá đều có cách sắp xếp này.','@48','clarified')
R(51,'B','Lục lạp là bào quan; diệp lục là sắc tố, còn thylakoid là cấu trúc bên trong lục lạp.','qa21-g11-l4-s1-e104f9ca9f')
R(52,'B','Mía, ngô và rau dền là các ví dụ C₄ dùng trong đề. Câu luyện bổ sung dùng mía, ngô, cao lương để gắn với danh sách ở câu 130.','@52','agrees','c4')
R(53,'C','Dứa, nhiều xương rồng và cây thuốc bỏng là các ví dụ CAM.','@53')
R(54,'C','Lúa, các cây khoai được nêu theo cách hiểu thông thường của bài, sắn và đậu thuộc nhóm C₃. “Khoai” nên ghi rõ loài như khoai tây.','@130','clarified')
R(55,'B','Chu trình Calvin diễn ra trong stroma (chất nền) lục lạp; cách gọi pha tối không có nghĩa chỉ xảy ra vào ban đêm.','qa21-g11-l4-s5-d4659ed5df qa21-g11-l4-s5-d9ea430286')
R(56,'D khi hỏi nhóm chlorophyll','Chlorophyll a và b thuộc nhóm diệp lục. Nếu hỏi riêng sắc tố trung tâm phản ứng thì chỉ chlorophyll a; đó là câu hỏi khác.','@56 qa21-g11-l4-s3-38f906e083','clarified')
R(57,'A','ATP cung cấp năng lượng, NADPH cung cấp lực khử cho các phản ứng đồng hóa CO₂ của Calvin.','qa21-g11-l4-s4-94ffca2413')
R(58,'A','Oxygen là khí được giải phóng khi quang hợp phân li nước và được dùng trong hô hấp hiếu khí.','qa21-g11-l4-s2-c0aa8a7c14')
R(59,'A (ống 1) theo bố trí hình','Ống 1 được chiếu sáng và có NaHCO₃ cung cấp carbon vô cơ. So sánh giả thiết lượng rong/điều kiện khác tương đương và nguồn carbon giới hạn ở ống không bổ sung.','@59','clarified')
R(60,'C','ALPG trong đề tương ứng G3P (triose phosphate); phần sản phẩm ra khỏi chu trình là tiền chất tổng hợp đường.','qa21-g11-l4-s10-f1c10adcf0')
R(61,'D là ý định của đề nhưng phải sửa “không hấp thụ” thành “hấp thụ ít hơn”','Lá phản xạ và truyền qua tương đối nhiều ánh sáng lục, không phải tuyệt đối không hấp thụ ánh sáng lục. Giữ phiên bản đã chỉnh thay vì học thuộc mệnh đề sai tuyệt đối.','qa21-g11-l4-s11-044d7d73ab','corrected','light')
R(62,'C','Sản phẩm ổn định đầu tiên của cố định CO₂ kiểu C₃ là 3-PGA (APG), có 3 carbon.','qa21-g11-l4-s6-efaa4e221d')
R(63,'B','Pha sáng chuyển quang năng thành năng lượng hóa học liên quan ATP và NADPH, sử dụng tiếp trong quá trình cố định carbon.','qa21-g11-l4-s4-94ffca2413')
R(64,'C','Quang hệ chứa sắc tố cùng các thành phần chuỗi electron nằm trên màng thylakoid, không ở xoang thylakoid.','qa21-g11-l4-s3-eeafe07039')
R(65,'A','Sản phẩm cố định CO₂ ban đầu ở con đường C₄ là oxaloacetate (OAA/AOA), hợp chất 4 carbon.','qa21-g11-l4-s7-daa9013752')
R(66,'C trong giai đoạn ngay sau tắt sáng','ATP/NADPH giảm khiến bước khử APG chậm, làm APG có thể tích lũy tạm thời. Về sau các bước còn lại cũng bị hạn chế.','@66','clarified')
R(67,'A','Hô hấp sáng tiêu thụ O₂ và có bước giải phóng CO₂ trong điều kiện có ánh sáng. Không đồng nhất với quang hợp giải phóng O₂.','@67')
R(68,'A theo quy ước kiến thức phổ thông của đề','Con số 90–95% là cách ước lượng thường dùng khi nói đóng góp của quang hợp vào chất khô/năng suất. Không phải hằng số đúng với mọi loài và mọi cách đo năng suất; không dùng để suy tỷ lệ chính xác cho một cây cụ thể.','qa21-g11-l4-s2-dafd8652a0 qa21-g11-l4-s14-3328c5eca4','convention')
R(69,'C','Đồ thị cho thấy thu CO₂ chủ yếu ban đêm, khí khổng đóng nhiều ban ngày: dấu hiệu điển hình của CAM trong bối cảnh bài. Chú ý trục phải: phía trên là đóng tối đa.','qa21-g11-l4-s8-e9dd73ba25','agrees','calvin')
R(70,'B','Phương trình tổng quát có ánh sáng: 6CO₂ + 12H₂O → C₆H₁₂O₆ + 6O₂ + 6H₂O. Đây là phương trình tổng quát, không mô tả sản phẩm đầu tiên của Calvin.','@70','clarified')
R(71,'C','Đường phân → bước tạo acetyl-CoA → chu trình Krebs → chuỗi truyền electron. Phương án C nêu đúng thứ tự ba giai đoạn lớn được liệt kê.','@71','clarified')
R(72,'C','Mỗi acetyl-CoA hoàn thành một lượt Krebs giải phóng 2 CO₂. Hai lượt: 4 CO₂, chưa cộng CO₂ từ oxi hóa pyruvate.','@72')
R(73,'D; cùng ý với câu 67','Thứ tự phương án đã đổi so với câu 67, nhưng nội dung đúng vẫn là hấp thụ O₂ và giải phóng CO₂ ngoài sáng.','@67')
R(74,'C','Ethanol là sản phẩm hữu cơ đặc trưng của lên men rượu; CO₂ cũng được giải phóng.','@74')
R(75,'A','Hô hấp cung cấp ATP/năng lượng cho các hoạt động của cây, đồng thời cung cấp chất trung gian cho sinh tổng hợp.','qa21-g11-l6-s1-5b56ac186d qa21-g11-l6-s2-6d1fb59a5b')
R(76,'A nếu nói hô hấp hiếu khí hoàn toàn','Chất hữu cơ được oxi hóa, tạo CO₂, H₂O và giải phóng năng lượng. Chữ “hô hấp” của câu nên ghi rõ hiếu khí để phân biệt lên men.','qa21-g11-l6-s1-7576654100','clarified')
R(77,'Không xác định duy nhất cho mọi thực vật','Khóa B=40–45°C là con số của đề, nhưng nhiệt độ tối đa thay đổi theo loài, mô và điều kiện. Không đủ dữ kiện chọn một khoảng như quy luật chung; không trộn tối đa với tối ưu.','qa21-g11-l6-s5-754a3c0685','needs-context')
R(78,'D; cùng thứ tự với câu 71','Thứ tự phương án đổi nhưng đường phân vẫn trước Krebs và chuỗi truyền electron. Không tạo bản câu hỏi trùng chỉ để đổi chữ đáp án.','@71')
R(79,'C','Đường phân là bước chung khi phân giải glucose trước khi chuyển sang lên men hoặc hô hấp hiếu khí.','@79')
R(80,'Cần nêu loài, mô và giai đoạn; không có cơ sở chọn rễ luôn cao nhất','Khóa A không phải quy luật chung. Hạt nảy mầm, hoa đang phát triển, mô phân sinh hoặc các cơ quan khác có thể hô hấp mạnh. Câu luyện thay thế nói rõ mô đang sinh trưởng.','@80','needs-context')
R(81,'C; lặp mục tiêu của câu 79','Vẫn là đường phân. Hai câu chỉ khác một vài cách viết.','@79')
R(82,'B','Chuỗi truyền electron hô hấp ở tế bào thực vật nhân thực nằm trên màng trong ti thể.','@82')
R(83,'C (điểm 4, điểm 5)','Điểm bù ánh sáng là hoành độ tại đó hai đường cường độ quang hợp/hô hấp bằng nhau (4); bão hòa là hoành độ nơi quang hợp bắt đầu đạt trần (5), không phải tung độ.','qa21-g11-l4-s11-c69d6a30fc qa21-g11-l4-s11-da20072ac9')
R(84,'A','Ngập úng hạn chế khuếch tán O₂ vào đất, làm giảm hô hấp hiếu khí/ATP và có thể tích lũy sản phẩm lên men gây hại. Đây không chỉ là cây hút quá nhiều nước.','qa21-g11-l6-s4-53e8a1632a qa21-g11-l3-s5-89739107bf')
R(85,'D theo quy ước cũ; không có đáp án hiện đại phù hợp trong bốn lựa chọn','36–38 ATP sử dụng cách quy đổi cũ. Mô hình thường dùng hiện nay ở nhân thực cho khoảng 30–32 ATP tùy shuttle/hiệu suất. Câu mới nêu hẳn 10 NADH×2,5 + 2 FADH₂×1,5 + 4 = 32.','@85','convention','atpyield oxidation')
R(86,'B trong hai con đường lên men được học','Pyruvate có thể chuyển thành ethanol (kèm CO₂) hoặc lactate tùy con đường/sinh vật. Không có nghĩa một phân tử pyruvate đồng thời cho cả hai.','@74 qa21-g10-l30-s1-2ffe13a3ce','clarified')
R(87,'D','Một glucose có 6 carbon được đường phân thành hai pyruvate, mỗi phân tử 3 carbon.','qa21-g10-l30-s1-cf65123e89')
R(88,'B theo quy đổi cũ; đề còn thiếu đơn vị cơ chất và quy ước','34 ATP thường là 10 NADH×3 + 2 FADH₂×2 của quy ước cũ cho một glucose. Với 2,5/1,5 thì phần oxi hóa lí thuyết là 28 ATP, chưa cộng ATP mức cơ chất.','@88','convention','atpyield')
R(90,'a: cần giới hạn phạm vi; b: S; c: S; d: S','a không đúng như một điều kiện bắt buộc của mọi sinh vật: đơn bào không có cơ quan. b chất hấp thụ còn phải chuyển hóa; c tế bào có sinh tổng hợp; d chất thải cần được đào thải, không mặc nhiên tái hấp thu.','@90 qa21-g11-l1-s2-046628a4ec qa21-g11-l1-s1-cd75b9ca73','ambiguous')
R(92,'a: Đ nếu chỉ biểu bì rễ; b: S; c: diễn đạt chưa rõ; d: Đ theo mô hình nước đất của bài','Lông hút thuộc biểu bì rễ, vì vậy khóa a=S không hợp lí nếu “biểu bì” là biểu bì rễ. Nước thẩm thấu thụ động. c trộn tế bào chất với không bào: cần phân biệt symplast và đường xuyên màng, không bỏ đường gian bào. Nước bị giữ quá chặt có thể không sẵn có cho rễ.','qa21-g11-l2-s2-980c010916 qa21-g11-l2-s2-aaa7c6f098 @113','ambiguous','roots transport')
R(93,'a: Đ; b: Đ với nghĩa yếu tố quan trọng; c: Đ theo ý môi trường vận chuyển; d: cần làm rõ','Nước chiếm phần lớn sinh khối tươi, có vai trò dung môi, môi trường phản ứng và vận chuyển. d giống mô tả vai trò Ca hơn, nhưng không nên biến khóa S thành khẳng định nước không tương tác với màng, enzyme hay tín hiệu.','qa21-g11-l2-s1-eada8daa0a qa21-g11-l2-s1-d564a24977 @31','ambiguous','water minerals')
R(94,'a: S; b: S; c: Đ; d: Đ','Dòng nước/khoáng điển hình qua mạch gỗ chứ không phải rễ đẩy nước lên mạch rây. Mạch gỗ chủ yếu từ rễ lên lá; áp suất rễ và lực hút do thoát hơi nước có thể tham gia.','qa21-g11-l2-s3-4775b92ecb @123 qa21-g11-l2-s4-6321a19ec7')
R(95,'a: Đ; b: S; c: Đ; d: Đ','Bón đúng loại, đúng lúc, đúng cách và đủ lượng theo nhu cầu. Bón càng nhiều không bảo đảm càng tốt.','qa21-g11-l2-s12-6ecfb11de0 qa21-g11-l2-s5-28b57b9845')
R(96,'a: cần sửa phạm vi; b: S; c: S; d: S','Không thể coi toàn bộ giới hạn sinh thái là quan hệ tỉ lệ thuận tuyến tính. Tăng nhiệt trong khoảng dưới tối ưu có thể tăng hấp thụ, nhưng vượt tối ưu làm chức năng rễ giảm; phụ thuộc loài và điều kiện.','qa21-g11-l2-s10-51c7fbdb10','ambiguous')
R(97,'a: Đ; b: Đ; c: Đ; d: Đ','Nước là thành phần tế bào, dung môi/vận chuyển, tham gia điều hòa nhiệt và làm nguyên liệu hoặc môi trường cho phản ứng. Không có nghĩa nước là dung môi cho mọi chất.','qa21-g11-l2-s1-eada8daa0a @31 qa21-g11-l4-s1-4a04da1623')
R(98,'a: S; b: S; c: S nếu hiểu xác hữu cơ được dùng trực tiếp; d: Đ','Rễ không sử dụng N₂ khí như nguồn N khoáng trực tiếp. Xác sinh vật chứa N hữu cơ, thường phải được phân giải/khoáng hóa trước khi trở thành nguồn NH₄⁺/NO₃⁻ dễ hấp thụ. Vì vậy khóa c=Đ cần sửa hoặc bổ sung bước này.','qa21-g11-l2-s6-f216acc436 qa21-g11-l2-s7-8e5af7b931 qa21-g11-l2-s6-9e28ece6e4','corrected','nitrogen')
R(99,'a: S; b: Đ trong điều kiện tương đương; c: Đ; d: S','Thoát hơi chủ yếu qua khí khổng ở nhiều lá, ngoài ra qua cuticle. Khí khổng không phải bào quan; tốc độ liên quan độ mở, không phải đơn giản độ dày của “khí khổng”.','qa21-g11-l2-s4-7dbce942fe qa21-g11-l2-s4-88565097dc qa21-g11-l3-s4-53934c3ebb')
R(100,'a: Đ; b: S theo vai trò đặc trưng được hỏi; c: Đ; d: Đ','N có trong amino acid/protein, nucleotide và diệp lục. Điều hòa thẩm thấu tế bào bảo vệ thường gắn với K⁺ và các chất tan khác, không phải vai trò đặc trưng trực tiếp của nitrogen như câu b.','qa21-g11-l2-s5-77b112ce2f @100','clarified')
R(101,'a: Đ; b: Đ; c: Đ; d: Đ','Đồ thị minh họa thiếu phân làm giảm năng suất, mức phù hợp cho năng suất cao, quá mức có thể gây độc. Tác động môi trường ở b cần kiến thức bổ sung, không thể đọc riêng từ trục năng suất.','qa21-g11-l2-s5-28b57b9845 qa21-g11-l2-s12-6ecfb11de0','clarified')
R(102,'a: Đ theo mô hình thí nghiệm; b: Đ có điều kiện kiểm soát; c: S; d: S','1/2 giúp xét bổ sung nguồn carbon khi cùng chiếu sáng; 1/3 giúp xét ánh sáng. Trong bình kín O₂ ròng còn phụ thuộc hô hấp. Không thể kết luận mọi bình đều tăng O₂ khi tăng nhiệt; NaHCO₃ còn ảnh hưởng pH nên cần kiểm soát khi nghiên cứu chính xác.','@102 @59 qa21-g11-l6-s7-330d0b85dd','clarified')
R(103,'a: Đ; b: S; c: Đ; d: S','Theo hình: I là O₂, II là chất khử NADPH, III là pha sáng, IV là chu trình Calvin. ATP và NADPH từ pha sáng dùng trong Calvin.','qa21-g11-l4-s4-94ffca2413 qa21-g11-l4-s4-ff73e0065a qa21-g11-l4-s5-d4659ed5df')
R(105,'a: S; b: Đ; c: Đ; d: S khi đọc đúng chữ “chỉ”','Thiếu O₂ khi úng làm giảm hô hấp hiếu khí; hô hấp cung cấp chất trung gian và mạnh ở mô hoạt động. Hô hấp sáng không chỉ có ở C₃: C₄ vẫn có thể xảy ra ở mức thấp. Khóa d=Đ của đề quá tuyệt đối.','qa21-g11-l6-s4-53e8a1632a qa21-g11-l6-s2-6d1fb59a5b @80 @67','corrected','photoresp')
R(106,'a: S; b: Đ; c: S; d: S','Thí nghiệm nhận biết CO₂ từ hạt nảy mầm bằng nước vôi. NaOH (không phải Na(OH)₂) có thể hấp thụ CO₂ nhưng không tạo cùng kết tủa CaCO₃; phép thử không xác định trực tiếp tiêu thụ O₂ hay trao đổi nước.','qa21-g11-l7-s1-fe0f9657d0 @106','clarified','limewater')
R(108,'a: Đ trong bối cảnh tiêu hao chất dự trữ; b: Đ theo bố trí; c: S; d: cần sửa cơ chế','Tuần 2 là N₂ tinh khiết: không thể có giai đoạn sau hô hấp hiếu khí khi không được cấp O₂. Tuần 3 CO₂ tăng rồi ổn định; hình hỗ trợ mô tả đó nhưng không chứng minh riêng nguồn cơ chất. Pyruvate phải thành acetyl-CoA trước khi vào Krebs.','@108 qa21-g11-l6-s6-cd307229dc @71','clarified','oxidation krebs')
R(112,'Thế nước/nồng độ muối của đất; pH; độ thoáng/O₂; nhiệt độ; tình trạng rễ','Đây là các yếu tố chính liên quan hấp thụ nước. Không chỉ nhìn lượng nước tổng cộng: nước bị giữ quá chặt hoặc đất mặn vẫn có thể làm cây khó hút nước.','@112 qa21-g11-l2-s2-5b5847104d qa21-g11-l2-s10-51c7fbdb10 qa21-g11-l2-s11-6facc7d28a')
R(113,'Đường gian bào (apoplast) và đường tế bào chất liên thông (symplast)','Apoplast đi qua thành và khoảng gian bào; symplast qua tế bào chất nối bằng cầu sinh chất. Cách phân chia chi tiết còn có đường xuyên màng; không đồng nhất qua không bào với symplast.','@113','clarified')
R(114,'Chặn dòng apoplast ở nội bì, buộc nước/chất tan đi qua màng theo lộ trình thích hợp trước khi vào trụ giữa','Đai Caspari tạo hàng rào giúp kiểm soát chất vào mô dẫn. Nó không ngăn hoàn toàn mọi nước vào rễ.','@114')
R(115,'Nước vào rễ chủ yếu bằng thẩm thấu theo gradient thế nước','Qua màng thấm chọn lọc, nước đi từ thế nước cao đến thấp. Rễ không bơm chủ động từng phân tử nước bằng ATP; ATP có thể gián tiếp duy trì gradient qua vận chuyển ion. Độ giữ nước của đất cũng ảnh hưởng tính sẵn có.','qa21-g11-l2-s2-aaa7c6f098 qa21-g11-l2-s2-5029e34076','clarified')
R(116,'Nước là thành phần tế bào, dung môi và môi trường phản ứng; tham gia phản ứng, vận chuyển, duy trì sức trương và điều hòa nhiệt','Nêu ví dụ: nước cung cấp electron cho quang hợp, hòa tan ion, giúp tế bào trương, hấp thụ nhiệt khi bay hơi. Có vai trò duy trì trạng thái vật lí của chất nguyên sinh; không chỉ một chức năng.','qa21-g11-l2-s1-d564a24977 qa21-g11-l2-s1-eada8daa0a @31 qa21-g11-l4-s1-4a04da1623')
R(117,'Chủ yếu lực hút do thoát hơi nước phối hợp tính liên tục của cột nước (liên kết–lực căng)','Nước bay hơi ở lá tạo áp suất âm kéo cột nước trong gỗ; liên kết giữa phân tử nước và bám thành hỗ trợ duy trì cột nước. Áp suất rễ không đủ giải thích nước lên những cây rất cao và không bắt buộc ở mọi cây. Không kiểm chứng lại kỉ lục/chiều cao được kể trong đề.','@117','corrected','transport')
R(118,'Điều chỉnh thẩm thấu hạ thế nước tế bào và kiểm soát muối','Tích lũy chất tan phù hợp giúp giữ thế nước thấp hơn môi trường để nhận nước. Cây chịu mặn còn hạn chế ion độc bằng các cơ chế như loại muối ở rễ, phân chia vào không bào hoặc bài tiết tùy loài.','@118','clarified','salinity-research')
R(119,'Hạn chế khí lọt vào mạch gỗ, giúp duy trì tiếp xúc liên tục với nước','Cột nước bị gián đoạn bởi khí có thể làm giảm dẫn nước. Cắt dưới nước hoặc chuyển đầu cắt ngay vào nước giúp hạn chế nguy cơ đó; còn phải giữ nước/dụng cụ sạch và chăm sóc phù hợp.','@119','clarified','cutflowers')
R(120,'Xới nhẹ làm đất thoáng, giúp rễ hô hấp và phát triển; quản lí nước, khoáng và vùng rễ phù hợp','Có thể phá váng/xới nhẹ tránh làm đứt rễ, kiểm soát cỏ, tưới đủ, thoát úng, giảm mặn khi có điều kiện và bón hợp lí. Không xới sâu làm hại rễ hoặc coi xới đất thay thế mọi biện pháp tưới/thoát nước.','qa21-g11-l6-s6-7ab1e7589b qa21-g11-l2-s12-6ecfb11de0 @122','clarified')
R(121,'Phân tích theo thế nước đất, pH, O₂ và nhiệt độ','Muối cao làm thế nước đất giảm. pH quá lệch gây hại rễ/thay đổi khoáng sẵn có. Đất thiếu O₂ làm giảm hô hấp, ATP và chức năng rễ. Nhiệt quá thấp/cao có thể hạn chế hấp thụ; không luôn tỉ lệ thuận với nhiệt độ. Hấp thụ ion không đồng nhất cơ chế với nước.','qa21-g11-l2-s2-5b5847104d @112 qa21-g11-l2-s11-6facc7d28a qa21-g11-l2-s10-51c7fbdb10','clarified')
R(122,'Giải pháp của Minh hợp lí khi có nước ngọt và đường thoát; không bảo đảm cứu được mọi cây','Rửa mặn giúp đưa muối khỏi vùng rễ, cải thiện thế nước. Cần đánh giá đất, lượng nước, thoát nước, loài cây và mức tổn thương. An đúng về nguy cơ gây hại nhưng sai nếu khẳng định không bao giờ cải thiện được.','@122 qa21-g11-l2-s2-5b5847104d','clarified','salt-extension')
R(123,'Áp suất rễ có thể đẩy dịch mạch gỗ ra vết cắt','Rễ còn hoạt động có thể tạo áp suất dương. Không quy dịch ứa này cho lực hút của phần tán đã cắt bỏ.','@123')
R(124,'Nếu chậu quá nhỏ hoặc điều kiện kém: hạn chế rễ, nước và dinh dưỡng','Cần nêu điều kiện so sánh. Trồng chậu không tất yếu chậm lớn hơn đất vườn; chậu đủ lớn, giá thể thoáng, cung cấp nước/khoáng tốt có thể khắc phục giới hạn.','@124','clarified','root-volume')
R(125,'Mạch gỗ hoạt động ở gỗ dác và mạch rây phía ngoài vẫn còn liên tục','Khoang rỗng ở lõi có thể không cắt đứt mô dẫn bên ngoài nên cây còn sống. Gỗ lõi vẫn có chức năng nâng đỡ; thân rỗng có thể yếu, không được coi hoàn toàn vô tác dụng hay an toàn.','@125','corrected','stems')
R(126,'Chưa thể xác định duy nhất: hình thiếu chú giải cột','Đề cho khóa 1 nhưng không ghi cột trắng/nâu là hút hay thoát. Nếu trắng=hút, nâu=thoát thì chỉ III có hút≥thoát (1 cây). Nếu ngược lại thì I, II, IV (3 cây). Không suy chú giải từ khóa để giả vờ dữ kiện đầy đủ; không đưa câu gốc vào chấm tự động.','','missing-context')
R(127,'Apoplast: thành/khe gian bào; symplast: tế bào chất nối qua cầu sinh chất; khác điểm qua màng và kiểm soát','Apoplast chưa đi qua màng trên đoạn vỏ rễ, bị đai Caspari hạn chế; symplast vào tế bào phải qua màng và tiếp tục qua cầu sinh chất. Không gọi “lọc sạch/không sạch” hoặc khẳng định luôn ít/nhiều nước nếu thiếu điều kiện.','@113 @114','corrected','roots casparian')
R(128,'Làm tổn thương mạch rây/tầng sinh mạch, cản phân phối chất hữu cơ và tăng nguy cơ nhiễm bệnh','Bóc vòng quanh thân đặc biệt nguy hiểm vì cắt đường cung cấp đường cho rễ. Ngăn phá vỏ, bảo vệ khỏi chấn thương thêm và nhờ người chăm sóc cây đánh giá vết lớn. Không mở rộng vết thương hoặc mặc định bôi “thuốc liền sẹo”; hướng dẫn chăm sóc cây không khuyến cáo bôi thường quy.','@128','corrected','stems treecare')
R(129,'So sánh cành hoa trắng trong nước màu và nước không màu; quan sát thuốc nhuộm trong mạch gỗ','Dùng cành tương đương, cùng thời gian/điều kiện. Mẫu nước không màu là đối chứng. Quan sát màu ở cánh và lát cắt thân cho thấy đường đi của nước màu qua mạch gỗ; không riêng thí nghiệm này mà chứng minh toàn bộ thành phần muối khoáng hay dòng mạch rây. Cắt mẫu theo hướng dẫn an toàn trong lớp.','qa21-g11-l3-s2-3ce102e01d qa21-g11-l3-s2-c82cdc39bf','clarified')
R(130,'4 theo cách hiểu “khoai” là loài C₃ như khoai tây','Lúa, khoai tây, sắn, đậu là C₃. Cao lương, ngô, mía là C₄; xương rồng, dứa, thanh long là các ví dụ CAM của bài.','@130','clarified')
